// Generated by IqwanEngine
import React, { useState, useEffect, lazy, Suspense } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Region, RoadtourStateData, IBRegionData, CommunityLinks, SiteContent } from './types';
import {
  INITIAL_ROADTOUR_2_STATES,
  INITIAL_ROADTOUR_1_STATES,
  INITIAL_ROADTOUR_STATES,
  IB_REGIONS_DATA,
  INITIAL_COMMUNITY_LINKS,
  INITIAL_SITE_CONTENT
} from './data/initialData';
import { Layout } from './components/Layout';

// Lazy Loaded Sections
const HomePage = lazy(() => import('./components/HomePage').then(m => ({ default: m.HomePage })));
const AboutSection = lazy(() => import('./components/AboutSection').then(m => ({ default: m.AboutSection })));
const VipSignalSection = lazy(() => import('./components/VipSignalSection').then(m => ({ default: m.VipSignalSection })));
const OwlAlgoSection = lazy(() => import('./components/OwlAlgoSection').then(m => ({ default: m.OwlAlgoSection })));
const RoadtourSection = lazy(() => import('./components/RoadtourSection').then(m => ({ default: m.RoadtourSection })));
const IBDevelopmentSection = lazy(() => import('./components/IBDevelopmentSection').then(m => ({ default: m.IBDevelopmentSection })));
const BasicEducationSection = lazy(() => import('./components/BasicEducationSection').then(m => ({ default: m.BasicEducationSection })));
const FindUsSection = lazy(() => import('./components/FindUsSection').then(m => ({ default: m.FindUsSection })));
const NewsTerminal = lazy(() => import('./components/NewsTerminal'));

import { LightboxModal } from './components/LightboxModal';
import { RegistrationModal, RegistrationTabType } from './components/RegistrationModal';
import { AdminCMSModal } from './components/AdminCMSModal';
import { LiveEventAlert } from './components/LiveEventAlert';
import ScrollToTop from './components/common/ScrollToTop';

/**
 * Loading Fallback for Suspense
 */
function SectionLoading() {
  return (
    <div className="min-h-[60vh] w-full flex items-center justify-center">
      <div className="flex flex-col items-center space-y-4">
        <div className="w-12 h-12 rounded-full border-2 border-amber-500/20 border-t-amber-500 animate-spin" />
        <span className="text-xs font-mono text-amber-500/60 uppercase tracking-widest animate-pulse">
          OWLFX ARCHITECTURE LOADING...
        </span>
      </div>
    </div>
  );
}

export default function App() {
  const [securityToast, setSecurityToast] = useState<{ show: boolean; message: string }>({
    show: false,
    message: '',
  });

  useEffect(() => {
    let toastTimer: ReturnType<typeof setTimeout>;

    const triggerSecurityNotice = (msg: string) => {
      setSecurityToast({ show: true, message: msg });
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => {
        setSecurityToast({ show: false, message: '' });
      }, 2400);
    };

    const handleContextMenu = (e: MouseEvent) => {
      e.preventDefault();
      triggerSecurityNotice('Perlindungan Media & Hak Cipta OWLFX Aktif. Klik kanan disekat.');
    };

    const handleDragStart = (e: DragEvent) => {
      e.preventDefault();
      triggerSecurityNotice('Perlindungan Kandungan: Penarikan imej (drag-and-drop) disekat.');
    };

    const handleKeyDown = (e: KeyboardEvent) => {
      const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0;
      const ctrlOrCmd = isMac ? e.metaKey : e.ctrlKey;

      if (e.key === 'F12') {
        e.preventDefault();
        e.stopPropagation();
        triggerSecurityNotice('Pintasan pembangun disekat untuk melindungi integriti platform.');
        return;
      }

      if (ctrlOrCmd && e.shiftKey && (e.key === 'I' || e.key === 'i' || e.key === 'J' || e.key === 'j' || e.key === 'C' || e.key === 'c')) {
        e.preventDefault();
        e.stopPropagation();
        triggerSecurityNotice('Pemeriksaan elemen (Inspect Element) disekat.');
        return;
      }

      if (ctrlOrCmd && (e.key === 'u' || e.key === 'U')) {
        e.preventDefault();
        e.stopPropagation();
        triggerSecurityNotice('Paparan kod sumber disekat.');
        return;
      }

      if (ctrlOrCmd && (e.key === 's' || e.key === 'S')) {
        e.preventDefault();
        e.stopPropagation();
        triggerSecurityNotice('Penyimpanan halaman secara luar talian disekat.');
        return;
      }
    };

    window.addEventListener('contextmenu', handleContextMenu);
    window.addEventListener('dragstart', handleDragStart);
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('contextmenu', handleContextMenu);
      window.removeEventListener('dragstart', handleDragStart);
      window.removeEventListener('keydown', handleKeyDown);
      clearTimeout(toastTimer);
    };
  }, []);

  const [currentRegion] = useState<Region>(() => {
    const saved = localStorage.getItem('owlfx_region');
    return (saved === 'ID' ? 'ID' : 'MY') as Region;
  });

  const [statesV2Data, setStatesV2Data] = useState<RoadtourStateData[]>(() => {
    const saved = localStorage.getItem('owlfx_roadtour_states_v2');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error('Failed to parse saved roadtour states v2', e);
      }
    }
    return INITIAL_ROADTOUR_2_STATES;
  });

  const [statesV1Data, setStatesV1Data] = useState<RoadtourStateData[]>(() => {
    const saved = localStorage.getItem('owlfx_roadtour_states_v1');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error('Failed to parse saved roadtour states v1', e);
      }
    }
    return INITIAL_ROADTOUR_1_STATES;
  });

  const [siteContent, setSiteContent] = useState<SiteContent>(() => {
    const saved = localStorage.getItem('owlfx_site_content');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error('Failed to parse saved site content', e);
      }
    }
    return INITIAL_SITE_CONTENT;
  });

  const [ibData, setIBData] = useState<Record<'MY' | 'ID', IBRegionData>>(() => {
    const saved = localStorage.getItem('owlfx_ib_data');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error('Failed to parse saved ib data', e);
      }
    }
    return IB_REGIONS_DATA;
  });

  const [communityLinks, setCommunityLinks] = useState<CommunityLinks>(() => {
    const saved = localStorage.getItem('owlfx_community_links');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error('Failed to parse saved community links', e);
      }
    }
    return INITIAL_COMMUNITY_LINKS;
  });

  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [lightboxImages, setLightboxImages] = useState<{ url: string; caption?: string; title?: string }[]>([]);
  const [lightboxIndex, setLightboxIndex] = useState(0);

  const [regModalOpen, setRegModalOpen] = useState(false);
  const [regModalTab] = useState<RegistrationTabType>('my-community');

  const [adminModalOpen, setAdminModalOpen] = useState(false);
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState<boolean>(() => {
    const token = sessionStorage.getItem('owlfx_admin_auth') || localStorage.getItem('owlfx_admin_auth');
    return !!token;
  });

  const handleAdminLoginSuccess = (token: string) => {
    setIsAdminAuthenticated(true);
    sessionStorage.setItem('owlfx_admin_auth', token);
    localStorage.setItem('owlfx_admin_auth', token);
    setSecurityToast({
      show: true,
      message: 'Hi IqwanEngine. Sesi Pentadbir OWLFX telah disahkan dengan selamat.',
    });
  };

  const handleAdminSignOut = () => {
    setIsAdminAuthenticated(false);
    sessionStorage.clear();
    localStorage.removeItem('owlfx_admin_auth');
    setSecurityToast({
      show: true,
      message: 'Sesi Pentadbir telah dilog keluar dan cache dipadamkan.',
    });
  };

  const handleUpdateStatesV2Data = (newStates: RoadtourStateData[]) => {
    setStatesV2Data(newStates);
    localStorage.setItem('owlfx_roadtour_states_v2', JSON.stringify(newStates));
  };

  const handleUpdateStatesV1Data = (newStates: RoadtourStateData[]) => {
    setStatesV1Data(newStates);
    localStorage.setItem('owlfx_roadtour_states_v1', JSON.stringify(newStates));
  };

  const handleUpdateSiteContent = (newContent: SiteContent) => {
    setSiteContent(newContent);
    localStorage.setItem('owlfx_site_content', JSON.stringify(newContent));
  };

  const handleUpdateIBData = (newIBData: Record<'MY' | 'ID', IBRegionData>) => {
    setIBData(newIBData);
    localStorage.setItem('owlfx_ib_data', JSON.stringify(newIBData));
  };

  const handleUpdateCommunityLinks = (newLinks: CommunityLinks) => {
    setCommunityLinks(newLinks);
    localStorage.setItem('owlfx_community_links', JSON.stringify(newLinks));
  };

  const handleResetDefaults = () => {
    setStatesV2Data(INITIAL_ROADTOUR_2_STATES);
    setStatesV1Data(INITIAL_ROADTOUR_1_STATES);
    setSiteContent(INITIAL_SITE_CONTENT);
    setIBData(IB_REGIONS_DATA);
    setCommunityLinks(INITIAL_COMMUNITY_LINKS);
    localStorage.removeItem('owlfx_roadtour_states_v2');
    localStorage.removeItem('owlfx_roadtour_states_v1');
    localStorage.removeItem('owlfx_site_content');
    localStorage.removeItem('owlfx_roadtour_states');
    localStorage.removeItem('owlfx_ib_data');
    localStorage.removeItem('owlfx_community_links');
  };

  const handleOpenLightbox = (images: { url: string; caption?: string; title?: string }[], index: number = 0) => {
    setLightboxImages(images);
    setLightboxIndex(index);
    setLightboxOpen(true);
  };

  return (
    <Router>
      <ScrollToTop />
      <Routes>
        {/* STANDALONE ROUTE - Absolute Isolation for News Terminal */}
        <Route path="/news" element={
          <Suspense fallback={<SectionLoading />}>
            <NewsTerminal />
          </Suspense>
        } />

        {/* ALL OTHER ROUTES WITH LAYOUT */}
        <Route path="*" element={
          <Layout
            onOpenAdmin={() => setAdminModalOpen(true)}
            communityLinks={communityLinks}
            securityToast={securityToast}
          >
            <Suspense fallback={<SectionLoading />}>
              <Routes>
                <Route path="/" element={<HomePage />} />
                <Route path="/about-us" element={<AboutSection />} />
                <Route
                  path="/ib-development"
                  element={
                    <IBDevelopmentSection
                      currentRegion={currentRegion}
                      ibData={ibData}
                      onOpenLightbox={handleOpenLightbox}
                    />
                  }
                />
                <Route
                  path="/owlalgo"
                  element={
                    <OwlAlgoSection
                      onOpenLightbox={handleOpenLightbox}
                    />
                  }
                />
                <Route
                  path="/roadtour"
                  element={
                    <RoadtourSection
                      statesV2Data={statesV2Data}
                      statesV1Data={statesV1Data}
                      statesData={statesV2Data}
                      onOpenLightbox={handleOpenLightbox}
                      isAdmin={isAdminAuthenticated}
                      onUpdateStatesV2Data={handleUpdateStatesV2Data}
                      onUpdateStatesData={handleUpdateStatesV2Data}
                      onOpenAdminLogin={() => setAdminModalOpen(true)}
                      onAdminSignOut={handleAdminSignOut}
                    />
                  }
                />
                <Route
                  path="/group-support"
                  element={
                    <VipSignalSection
                      onOpenLightbox={handleOpenLightbox}
                    />
                  }
                />
                <Route path="/education" element={<BasicEducationSection />} />

                <Route path="/contact" element={<FindUsSection />} />
                <Route path="/find-us" element={<FindUsSection />} />
                <Route path="*" element={<Navigate to="/" replace />} />
              </Routes>
            </Suspense>
          </Layout>
        } />
      </Routes>

      {/* Modals & Floating Elements */}
      <LightboxModal
        isOpen={lightboxOpen}
        onClose={() => setLightboxOpen(false)}
        images={lightboxImages}
        currentIndex={lightboxIndex}
        onNavigate={(newIdx) => setLightboxIndex(newIdx)}
      />

      <RegistrationModal
        isOpen={regModalOpen}
        onClose={() => setRegModalOpen(false)}
        defaultTab={regModalTab}
      />

      <AdminCMSModal
        isOpen={adminModalOpen}
        onClose={() => setAdminModalOpen(false)}
        statesV2Data={statesV2Data}
        statesV1Data={statesV1Data}
        onUpdateStatesV2Data={handleUpdateStatesV2Data}
        onUpdateStatesV1Data={handleUpdateStatesV1Data}
        statesData={statesV2Data}
        onUpdateStatesData={handleUpdateStatesV2Data}
        siteContent={siteContent}
        onUpdateSiteContent={handleUpdateSiteContent}
        ibData={ibData}
        onUpdateIBData={handleUpdateIBData}
        communityLinks={communityLinks}
        onUpdateCommunityLinks={handleUpdateCommunityLinks}
        onResetDefaults={handleResetDefaults}
        isAdminAuthenticated={isAdminAuthenticated}
        onLoginSuccess={handleAdminLoginSuccess}
        onSignOut={handleAdminSignOut}
      />

      <LiveEventAlert />
    </Router>
  );
}
